.c06-clipboard-panel{margin:9px 0;padding:8px 4px;border-top:1px solid var(--a-border,#ddd);font-size:12px}
.c06-clipboard-panel summary{min-height:38px;cursor:pointer;font-weight:600;padding:8px 3px}
.c06-clipboard-panel p{color:var(--a-subtle,#667);font-size:11px;line-height:1.45}
.c06-clipboard-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
.c06-clipboard-grid > .workspace-range{grid-column:1/-1}
.c06-clipboard-grid button{min-height:43px;text-align:center;padding:8px;border:1px solid var(--a-border,#ddd);border-radius:9px;background:var(--a-accent-soft,#fff1d7);color:inherit;font-size:11px}
.c06-clipboard-grid button:disabled{opacity:.43}
.c06-clipboard-panel small,.c06-clipboard-panel output{display:block;margin:8px 0;font-size:10px;color:var(--a-subtle,#667);line-height:1.45}

.c06-selection-panel{margin:9px 0;padding:8px 4px;border-top:1px solid var(--a-border,#ddd);font-size:12px}
.c06-selection-panel summary{min-height:38px;cursor:pointer;font-weight:600;padding:8px 3px}
.c06-selection-panel p{font-size:11px;line-height:1.5;color:var(--a-subtle,#667)}
.c06-selection-tools{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px;margin:7px 0}
.c06-selection-tools button,.c06-selection-save button{min-height:40px;padding:5px 7px;background:var(--a-accent-soft,#fff1d6);border:1px solid var(--a-border,#ddd);border-radius:8px;font-size:11px;color:inherit}
.c06-selection-tools button[aria-pressed="true"]{box-shadow:inset 0 0 0 2px var(--a-focus,#85501c)}
.c06-selection-tools button:disabled{opacity:.45}
.c06-selection-tools select,.c06-selection-save select{width:100%;min-height:40px;padding:6px;border:1px solid var(--a-border,#ddd);border-radius:8px;color:inherit;background:var(--a-surface,#fff)}
.c06-selection-save{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin:8px 0}
.c06-selection-save select{grid-column:1/-1}
.c06-selection-panel output{display:block;min-height:22px;color:var(--a-subtle,#667);font-size:11px}
.c06-selection-preview{position:absolute;inset:0;z-index:9;width:100%;height:100%;pointer-events:none;overflow:hidden}
.c06-selection-preview[data-empty="true"]{display:none}
.c06-selection-preview path{fill:#41c2eb14;stroke:#36acd6;stroke-width:2;stroke-dasharray:6 4;vector-effect:non-scaling-stroke}
.c06-selection-notice{pointer-events:none;position:absolute;top:10px;left:10px;z-index:9;padding:5px 7px;border:1px solid #60b9cd;border-radius:6px;background:#ffffffcf;color:#236275;font-size:10px}
.c06-selection-notice[hidden]{display:none}

.c06-auto-selection{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;align-items:center;margin:8px 0;padding:9px;border:1px solid var(--a-border,#ddd);border-radius:9px;background:var(--a-surface-soft,#fcfaf7)}
.c06-auto-selection select,.c06-auto-selection>.workspace-range,.c06-auto-selection>label{grid-column:1/-1;min-width:0}
.c06-auto-selection select,.c06-selection-brightness input[type=number]{min-height:36px;padding:5px 7px;border:1px solid var(--a-border,#ddd);border-radius:7px;background:var(--a-surface,#fff);color:inherit}
.c06-auto-selection label{font-size:11px;line-height:1.45}
.c06-auto-selection input[type=checkbox]{margin-right:7px;vertical-align:middle}
.c06-auto-selection>button{min-height:40px;border-radius:8px;border:1px solid var(--a-border,#ddd);background:var(--a-accent-soft,#fff0d5);color:inherit;font-size:11px}
.c06-auto-selection>button[aria-pressed=true]{box-shadow:inset 0 0 0 2px var(--a-focus,#85501c)}
.c06-selection-brightness{display:flex;gap:6px;margin-top:4px}
.c06-selection-brightness input{width:50%;min-width:0}
.c06-visibility{display:flex;align-items:center;gap:6px;margin:8px 0;padding:7px 6px;border-radius:7px;background:var(--a-surface-soft,#faf8f5);font-size:11px}
.c06-visibility input{flex:none}
.c06-drop-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;z-index:20;pointer-events:none;border:3px dashed #49c0b3;background:#d9f4eea6;color:#1e625d;font-size:14px;font-weight:600;padding:25px;text-align:center}
.c06-drop-overlay[hidden]{display:none}
.c06-drop-dialog{position:fixed;inset:12dvh auto auto 50%;transform:translateX(-50%);margin:0;width:min(500px,calc(100vw - 22px));background:var(--a-surface,#fff);color:inherit;border:1px solid var(--a-border,#ddd);border-radius:14px;box-shadow:0 20px 55px #101b2933;padding:18px;max-height:76dvh;overflow:auto}
.c06-drop-dialog::backdrop{background:#10203077}
.c06-drop-dialog h3{font-size:17px;margin:0 0 10px}
.c06-drop-dialog p{font-size:12px}
.c06-drop-actions{display:grid;gap:8px;margin:12px 0}
.c06-drop-actions button{min-height:45px;padding:10px;border:1px solid var(--a-border,#ddd);border-radius:9px;background:var(--a-accent-soft,#fff0d5);color:inherit}
.c06-drop-actions button:disabled{opacity:.5}

.c06-selection-brush{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin:8px 0;padding:8px;border:1px solid var(--a-border,#ddd);border-radius:9px;background:var(--a-surface-soft,#fbfaf6)}
.c06-selection-brush>button{min-height:40px;border:1px solid var(--a-border,#ddd);border-radius:8px;background:var(--a-accent-soft,#fff0d7);color:inherit;font-size:11px}
.c06-selection-brush>button[aria-pressed=true]{box-shadow:inset 0 0 0 2px var(--a-focus,#85501c)}
.c06-selection-brush>label{grid-column:1/-1;font-size:11px;display:grid;grid-template-columns:minmax(90px,1fr) minmax(70px,1.2fr);align-items:center;gap:7px}
.c06-selection-brush>.workspace-range{grid-column:1/-1;font-size:11px}
.c06-selection-brush input{min-width:0;width:100%;accent-color:#368da8}
.c06-selection-brush>label input[type=number]{min-height:37px;border:1px solid var(--a-border,#ddd);border-radius:7px;background:var(--a-surface,#fff);color:inherit;padding:5px}

/* C06-017: lightweight preview directly over the existing artwork view.
   Preview pixels are capped at 512px; exact placement is committed by Core. */
.c06-placement-preview{position:absolute;inset:0;z-index:16;pointer-events:none;overflow:hidden}
.c06-placement-image{position:absolute;left:0;top:0;transform-origin:0 0;opacity:.67;pointer-events:auto;touch-action:none;cursor:move;border:1px dashed #408fbc;box-shadow:0 0 0 1px #fff7;image-rendering:auto}
.c06-placement-toolbar{pointer-events:auto;position:absolute;right:8px;top:8px;display:flex;align-items:center;flex-wrap:wrap;gap:6px;max-width:min(460px,calc(100% - 18px));border:1px solid var(--a-border,#aaa);border-radius:9px;background:var(--a-surface,#fff);box-shadow:0 4px 14px #1234;padding:8px}
.c06-placement-toolbar output{flex:1 1 100%;font-size:11px;color:inherit}
.c06-placement-toolbar button{min-height:42px;padding:7px 12px;border-radius:7px;border:1px solid var(--a-border,#aaa);background:var(--a-accent-soft,#f2f6ff);color:inherit;font-size:12px}

/* Bounded pixel-exact preview for small selection-brush strokes. */
.c06-selection-brush-raster{position:absolute;left:0;top:0;z-index:10;pointer-events:none;transform-origin:0 0;image-rendering:pixelated}
/* Selection canvases are transparent overlays. The base canvas rule otherwise
   gives them a white background and overrides the browser's hidden display. */
.c06-mask-preview,.c06-selection-brush-raster{background:transparent}
.c06-mask-preview[hidden],.c06-selection-brush-raster[hidden]{display:none}

.c06-mask-preview,.c06-selection-brush-raster { background: transparent }
.c06-mask-preview[hidden],.c06-selection-brush-raster[hidden] { display: none }

.assist-previews { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px; }
.assist-previews figure { margin:0;min-width:0; }
.assist-previews canvas { display:block;max-width:100%;max-height:240px;object-fit:contain;
  background:repeating-conic-gradient(#bebebe 0% 25%,#eee 0% 50%) 0 0/14px 14px; }
.assist-previews canvas[hidden] { display:none; }

.exchange-print-preview { max-inline-size:100%;max-block-size:220px;object-fit:contain;
  background:repeating-conic-gradient(#bfc2c7 0% 25%,#ebebed 0% 50%) 0 0/16px 16px; }

