/* C05: Assets and reference board. No styles target artwork canvas. */
.c05-asset-panel,.c05-reference-editor{font-size:12px;display:flex;flex-direction:column;gap:8px;min-width:0}
.c05-asset-panel h4,.c05-reference-editor h4{margin:2px 0 0;font-size:14px}
.c05-asset-panel p,.c05-reference-editor p{font-size:11px;line-height:1.5;color:var(--a-subtle,#666);margin:0}
.c05-asset-search{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
.c05-asset-search input{grid-column:1/-1}
.c05-asset-search input,.c05-asset-search select,.c05-asset-actions select{width:100%;min-width:0;min-height:39px;padding:6px;border:1px solid var(--a-border,#ddd);border-radius:8px;background:var(--a-surface,#fff);color:inherit;font-size:11px}
.c05-asset-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
.c05-asset-actions button,.c05-reference-actions button,.c05-reference-row button,.c05-asset-entry-actions button{min-height:37px;border:1px solid var(--a-border,#ddd);border-radius:8px;padding:5px 8px;background:var(--a-accent-soft,#fff2d5);color:inherit;font-size:11px}
.c05-asset-results{min-height:46px;max-height:42dvh;overflow-y:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:7px}
.c05-asset-entry{border:1px solid var(--a-border,#ddd);border-radius:9px;padding:8px;display:flex;flex-direction:column;gap:7px;background:var(--a-surface,#fff)}
.c05-asset-entry-head{display:flex;flex-direction:column;gap:4px}
.c05-asset-entry-head strong{font-size:12px;overflow-wrap:anywhere}
.c05-asset-entry-head small{font-size:10px;color:var(--a-subtle,#666);line-height:1.3}
.c05-asset-entry-actions{display:flex;flex-wrap:wrap;gap:4px}
.c05-asset-panel>small,.c05-reference-editor output,.c05-asset-panel output{font-size:10px;color:var(--a-subtle,#666)}
.c05-reference-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
.c05-reference-list{max-height:35dvh;overflow:auto;display:flex;flex-direction:column;gap:6px}
.c05-reference-row{display:flex;flex-wrap:wrap;align-items:center;gap:4px;padding:6px;border:1px solid var(--a-border,#ddd);border-radius:8px}
.c05-reference-row span{flex:1 1 100%;font-size:11px;overflow-wrap:anywhere}
.c05-reference-layer{position:fixed;inset:0;pointer-events:none;z-index:14;overflow:visible}
.c05-reference-layer[hidden]{display:none}
.c05-reference-frame{position:absolute;pointer-events:auto;background:var(--a-surface,#fff);border:1px solid var(--a-border-strong,#ccc);border-radius:11px;box-shadow:0 12px 30px #10203044;display:flex;flex-direction:column;overflow:hidden;max-width:calc(100vw - 12px);max-height:calc(100dvh - 12px);min-width:160px;min-height:120px}
.c05-reference-frame.c05-reference-front{z-index:2}
.c05-reference-heading{flex:none;min-height:37px;display:flex;align-items:center;gap:5px;padding:3px 6px;touch-action:none;cursor:grab;background:var(--a-surface-soft,#fbfaf7)}
.c05-reference-heading strong{flex:1;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.c05-reference-heading button{min-height:32px;border:1px solid var(--a-border,#ddd);border-radius:6px;background:var(--a-accent-soft,#fff2d5);font-size:10px;color:inherit}
.c05-reference-image-area{flex:1;min-height:0;display:flex;align-items:center;justify-content:center;overflow:hidden;position:relative;touch-action:none;cursor:move;background:repeating-conic-gradient(#f5f4ef 0% 25%,#dddcd6 0% 50%) 50% / 20px 20px}
.c05-reference-image-area img{max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain;pointer-events:none;transform-origin:center center}
.c05-reference-image-area p{font-size:11px;padding:10px;background:#fff;color:#444}
.c05-reference-tools{flex:none;display:flex;flex-wrap:nowrap;overflow-x:auto;overscroll-behavior-x:contain;gap:3px;padding:4px 12px 6px 4px;background:var(--a-surface-soft,#fafafa)}
.c05-reference-tools button{flex:none;min-height:35px;padding:4px 7px;border:1px solid var(--a-border,#ddd);border-radius:6px;background:var(--a-surface,#fff);color:inherit;font-size:10px}
.c05-reference-resize{position:absolute;right:0;bottom:0;width:29px;height:31px;border:1px solid var(--a-border-strong,#ccc);border-radius:6px 0 0 0;background:var(--a-accent-soft,#fff2d5);touch-action:none;cursor:nwse-resize;color:inherit}
