}
@media (max-width:370px){
 .ih-header-inner,.ih-main{width:calc(100% - 24px)}
 .ih-brand-name{font-size:18px}
 .ih-nav-item{padding:9px 7px;font-size:11px}
 .ih-nav-icon{width:34px}
 .ih-welcome h1{font-size:42px}
 .ih-action-text strong{font-size:14px}
 .ih-discover-top h2{font-size:15px}
 .ih-start-choices{gap:7px}.ih-choice{padding:11px}
}
@media (max-height:520px) and (min-width:761px){
 .ih-main-grid{padding-top:30px}
 .ih-discover{min-height:445px}
 .ih-feature-visual{height:172px}
 .ih-welcome h1{font-size:54px}
}
@media (prefers-reduced-motion:reduce){
 .ih-root *, .ih-root *::before,.ih-root *::after{animation-duration:.001ms!important;transition-duration:.001ms!important;scroll-behavior:auto!important}
}

/* Production replaces QA document shortcuts with Home and the canonical Document routes. */
body[data-app-mode="production"] .canvas-top .document-actions{display:none!important}
body[data-app-mode="production"] .workspace-box[data-box-id="right.document"] .scalar-row{display:none!important}
body[data-app-mode="production"] .workspace-box[data-box-id="right.document"] [data-action="new"],
body[data-app-mode="production"] .workspace-box[data-box-id="right.document"] [data-action="open"],
body[data-app-mode="production"] .workspace-box[data-box-id="right.document"] [data-action="recover"]{display:none!important}

/* The approved M07 Aurora SVG icon family: no font-dependent pictograms. */
.ih-sparkle .ui-icon{width:19px;height:19px;display:block}
.ih-action-icon .ui-icon{width:25px;height:25px;display:block}
.ih-nav-icon .ui-icon{width:21px;height:21px;display:block}
.ih-choice-icon .ui-icon{width:26px;height:26px;display:block}
.ih-empty-spark .ui-icon{width:31px;height:31px;display:block}
.ih-detail-glyph{background:none;-webkit-background-clip:initial;background-clip:initial;color:#8B83EA}
.ih-detail-glyph .ui-icon{width:124px;height:124px;display:block;stroke-width:1.45}

.ih-works-tools{display:flex;gap:20px;align-items:end;margin:24px 0}.ih-works-tools label,.ih-name-field{display:flex;flex-direction:column;gap:8px;font-size:14px;color:#4f607a}.ih-works-tools label:first-child{flex:1}.ih-works-tools input,.ih-works-tools select,.ih-name-field input,.ih-name-field select{min-height:44px;width:100%;box-sizing:border-box;border:1px solid #d9e2f1;border-radius:12px;background:#fff;color:#222c40;padding:10px 14px;font:inherit}.ih-name-field{margin:16px 0}.ih-work-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:24px}.ih-work-card{min-width:0;background:#fff;border:1px solid #e0e6f1;border-radius:18px;overflow:hidden;box-shadow:0 5px 20px #53689308}.ih-work-preview{width:100%;height:220px;padding:18px;border:0;border-radius:0;display:flex;align-items:center;justify-content:center;background:repeating-conic-gradient(#f0f3f9 0 25%,#fff 0 50%) 50%/18px 18px;color:#64738d;cursor:pointer}.ih-work-preview img{display:block;max-width:100%;max-height:100%;object-fit:contain;box-shadow:0 3px 15px #384d6812}.ih-work-info{padding:16px}.ih-work-title{padding:0;display:block;max-width:100%;min-height:44px;text-align:left;font-size:17px;font-weight:650;background:transparent;border:0;overflow-wrap:anywhere;cursor:pointer}.ih-work-info p{font-size:12px;line-height:1.7;color:#5c6c83;margin:4px 0 12px}.ih-work-actions summary{cursor:pointer;min-height:44px;display:flex;align-items:center;gap:8px;font-size:13px;color:#4e6290}.ih-work-actions summary:after{content:'⌄'}.ih-work-actions button{display:block;width:100%;min-height:44px;text-align:left;background:#f7f9fe;border:1px solid #e1e7f3;margin-bottom:6px;border-radius:8px;padding:8px 12px;font:inherit;cursor:pointer}.ih-work-actions small{display:block;overflow-wrap:anywhere;color:#6b7891;font-size:10px;line-height:1.7}.ih-root :focus-visible{outline:3px solid #748def;outline-offset:3px}.ih-root [hidden]{display:none!important}
@media(max-width:600px){.ih-work-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ih-work-preview{height:150px;padding:10px}.ih-work-info{padding:10px}.ih-work-title{font-size:14px}.ih-works-tools{gap:12px;flex-wrap:wrap}.ih-works-tools label:first-child{flex-basis:100%}.ih-work-info p{font-size:11px}}

/* Temporary My Works reset button: shown only when ?debugWorks=1. */
.ih-debug-reset{border:1px solid #ddadad;background:#fff5f5;color:#a43838;border-radius:12px;min-height:44px;padding:0 14px;font:inherit;font-weight:650;cursor:pointer}
.ih-debug-reset:hover{background:#ffe9e9}.ih-debug-reset:disabled{opacity:.45;cursor:wait}.ih-debug-reset[hidden]{display:none!important}

.ih-works-controls{display:flex;align-items:center;justify-content:flex-end;gap:12px;flex-wrap:wrap}
@media(max-width:600px){.ih-works-controls{justify-content:flex-start}.ih-works-bar{align-items:flex-start;flex-direction:column;gap:10px}.ih-debug-reset{width:100%}}

.ih-recovery-item h2 { margin: 0; font-size: 1rem; }
.ih-recovery-item div { display: flex; flex-wrap: wrap; gap: .4rem; }
.ih-recovery-preview { width: min(160px, 100%); height: auto; }

.ih-canvas-setup { margin: 12px 0 4px }
.ih-canvas-setup > summary { min-height: 42px; padding: 9px 2px; cursor: pointer }
#ihSizeSummary { padding-inline-start: 6px; font-size: 12px; color: var(--ih-muted) }
.ih-canvas-setup .ih-size-presets { margin-top: 8px }

.ih-settings-controls { display: grid; gap: 20px; justify-items: start }
.ih-work-info { position: relative; padding-inline-end: 53px }
.ih-work-menu-toggle {
  position: absolute;
  inset: 7px 7px auto auto;
  display: grid;
  place-items: center;
  width: 44px;
  min-height: 44px;
  padding: 0;
  border: 0;
  background: transparent;
}
.ih-work-menu {
  position: fixed;
  inset: auto;
  margin: 0;
  padding: 4px;
  box-sizing: border-box;
  max-height: calc(100dvh - 16px);
  overflow: auto;
  border: 1px solid #d9e2f1;
  border-radius: 10px;
  color: var(--ih-text, #222c40);
  background: #fff;
  box-shadow: 0 10px 22px #26396128;
}
.ih-work-menu button {
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: start;
  min-height: 44px;
  width: 100%;
  padding: 5px 8px;
  border: 0;
  background: transparent;
}
.ih-work-menu button:is(:hover,:focus-visible) { background: #edf2fd }
